// Checks on repository files that are not Rust code: CI workflows and site configuration.
// Each test names the finding of docs/security/BASELINE_FINDINGS.md it guards.

use std::path::{Path, PathBuf};

fn root() -> &'static Path {
    Path::new(env!("CARGO_MANIFEST_DIR"))
}

// With LF line ends, whatever `core.autocrlf` did to the checkout.
fn read(rel: &str) -> String {
    std::fs::read_to_string(root().join(rel))
        .unwrap_or_else(|e| panic!("read {rel}: {e}"))
        .replace("\r\n", "\n")
}

// Every workflow. `release.yml` was generated by cargo-dist and is now kept by hand
// (`allow-dirty = ["ci"]` in dist-workspace.toml).
fn workflows() -> Vec<PathBuf> {
    let mut out = Vec::new();
    for dir in [".github/workflows", "registry-template/.github/workflows"] {
        for entry in std::fs::read_dir(root().join(dir)).unwrap() {
            let path = entry.unwrap().path();
            let name = path.file_name().unwrap().to_string_lossy().into_owned();
            if name.ends_with(".yml") {
                out.push(path);
            }
        }
    }
    assert!(out.len() >= 5, "workflows not found: {out:?}");
    out
}

// B-S3: a tag or branch of an action can be moved to other code; a full commit hash cannot.
#[test]
fn actions_are_pinned_to_commit_hashes() {
    let mut bad = Vec::new();
    for path in workflows() {
        let text = std::fs::read_to_string(&path).unwrap();
        for (i, line) in text.lines().enumerate() {
            let Some(rest) = line
                .trim_start()
                .trim_start_matches("- ")
                .strip_prefix("uses: ")
            else {
                continue;
            };
            let spec = rest.split_whitespace().next().unwrap_or_default();
            let pinned = spec.rsplit_once('@').is_some_and(|(_, r)| {
                r.len() == 40
                    && r.bytes()
                        .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b))
            });
            if !pinned && !spec.starts_with("./") {
                bad.push(format!("{}:{}: {spec}", path.display(), i + 1));
            }
        }
    }
    assert!(
        bad.is_empty(),
        "actions not pinned to a commit:\n{}",
        bad.join("\n")
    );
}

// B-S4: without a `permissions:` block a job gets the repository's default token scope, which
// can include write access.
#[test]
fn ci_token_is_read_only() {
    let text = read(".github/workflows/ci.yml");
    let block: Vec<&str> = text
        .lines()
        .skip_while(|l| *l != "permissions:")
        .skip(1)
        .take_while(|l| l.starts_with("  "))
        .collect();
    assert_eq!(
        block,
        ["  contents: read"],
        "top-level permissions of ci.yml"
    );
    assert!(
        !text
            .lines()
            .any(|l| l.trim_start().starts_with("permissions:") && l.starts_with(' ')),
        "a job in ci.yml widens the permissions"
    );
}

// B-S1: Cloudflare Pages sends the headers of `site/public/_headers` (copied into the build) with
// every page of qxide.dev.
#[test]
fn site_sends_security_headers() {
    let text = read("site/public/_headers");
    let mut lines = text
        .lines()
        .filter(|l| !l.trim().is_empty() && !l.starts_with('#'));
    assert_eq!(lines.next(), Some("/*"), "headers must apply to every path");
    let headers: Vec<(String, String)> = lines
        .map(|l| {
            let (k, v) = l.trim().split_once(':').expect("`Name: value`");
            (k.to_ascii_lowercase(), v.trim().to_string())
        })
        .collect();
    let get = |name: &str| {
        headers
            .iter()
            .find(|(k, _)| k == name)
            .map(|(_, v)| v.as_str())
            .unwrap_or_else(|| panic!("missing {name}"))
    };
    assert_eq!(get("x-content-type-options"), "nosniff");
    assert_eq!(get("x-frame-options"), "DENY");
    assert!(get("referrer-policy").starts_with("strict-origin"));
    let csp = get("content-security-policy");
    for part in [
        "frame-ancestors 'none'",
        "object-src 'none'",
        "base-uri 'self'",
    ] {
        assert!(csp.contains(part), "CSP lacks {part}: {csp}");
    }
}

// B-S7: the Vite dev server may read only the site and the examples it bundles, not the whole
// repository (target/, .git/, local files).
#[test]
fn dev_server_reads_only_the_site_and_examples() {
    let text = read("site/vite.config.ts");
    let start = text.find("allow: [").expect("server.fs.allow") + "allow: [".len();
    let list = &text[start..start + text[start..].find(']').unwrap()];
    let dirs: Vec<&str> = list
        .split(',')
        .map(|s| s.trim().trim_matches('\''))
        .filter(|s| !s.is_empty())
        .collect();
    assert_eq!(dirs, [".", "../examples/qx"], "server.fs.allow");
}

/// The lines of every `run:` script in a workflow, with the 1-based line number.
fn run_scripts(text: &str) -> Vec<(usize, String)> {
    let lines: Vec<&str> = text.lines().collect();
    let mut out = Vec::new();
    let mut i = 0;
    while i < lines.len() {
        let line = lines[i];
        let body = line.trim_start().trim_start_matches("- ");
        if let Some(rest) = body.strip_prefix("run:") {
            let indent = line.len() - line.trim_start().len();
            let rest = rest.trim();
            if rest == "|" || rest == ">" {
                i += 1;
                while i < lines.len()
                    && (lines[i].trim().is_empty()
                        || lines[i].len() - lines[i].trim_start().len() > indent)
                {
                    out.push((i + 1, lines[i].to_string()));
                    i += 1;
                }
                continue;
            }
            out.push((i + 1, rest.to_string()));
        }
        i += 1;
    }
    out
}

/// `permissions:` entries of each job (`job name -> lines`) and of the workflow (`""`).
fn permissions(text: &str) -> Vec<(String, Vec<String>)> {
    let mut out = Vec::new();
    let mut job = String::new();
    let lines: Vec<&str> = text.lines().collect();
    for (i, line) in lines.iter().enumerate() {
        if line.starts_with("  ") && !line.starts_with("   ") && line.trim_end().ends_with(':') {
            job = line.trim().trim_end_matches(':').to_string();
        }
        let indent = line.len() - line.trim_start().len();
        if line.trim() == "permissions:" {
            let entries = lines[i + 1..]
                .iter()
                .take_while(|l| l.len() - l.trim_start().len() > indent && !l.trim().is_empty())
                .map(|l| l.trim().replace('"', ""))
                .filter(|l| !l.starts_with('#'))
                .collect();
            out.push((
                if indent == 0 {
                    String::new()
                } else {
                    job.clone()
                },
                entries,
            ));
        }
    }
    out
}

// B-S2: PyPI uploads use Trusted Publishing (a short-lived OIDC token), not a stored API token.
#[test]
fn pypi_uploads_use_trusted_publishing() {
    let text = read(".github/workflows/pypi.yml");
    assert!(
        !text.contains("PYPI_API_TOKEN"),
        "pypi.yml still reads the API token"
    );
    assert!(!text.contains("password:"), "pypi.yml passes a password");
    let publish = permissions(&text)
        .into_iter()
        .find(|(job, _)| job == "publish")
        .expect("publish job permissions");
    assert_eq!(publish.1, ["contents: read", "id-token: write"]);
    assert!(
        text.contains("    environment:\n      name: pypi\n"),
        "publish runs in the `pypi` environment"
    );
}

// B-S5: only the job that creates the GitHub Release can write to the repository, and tag names
// reach shell scripts through `env`, not through `${{ }}` in the script text.
#[test]
fn release_workflow_keeps_write_access_and_tag_names_contained() {
    let text = read(".github/workflows/release.yml");
    let perms = permissions(&text);
    let workflow = perms
        .iter()
        .find(|(job, _)| job.is_empty())
        .expect("workflow permissions");
    assert_eq!(workflow.1, ["contents: read"]);
    let writers: Vec<&str> = perms
        .iter()
        .filter(|(_, e)| e.iter().any(|l| l.ends_with(": write")))
        .map(|(job, _)| job.as_str())
        .collect();
    assert_eq!(writers, ["host"], "jobs with write permissions");
    for (n, line) in run_scripts(&text) {
        assert!(
            !line.contains("github.ref_name") && !line.contains("needs.plan.outputs.tag"),
            "release.yml:{n} puts the tag into a script: {line}"
        );
    }
    assert!(read("dist-workspace.toml").contains("allow-dirty = [\"ci\"]"));
}

// B-S6: every file of a release has a checksum in `SHA256SUMS` and a GitHub build provenance
// attestation, so a download can be checked against this repository's workflow.
#[test]
fn release_files_are_checksummed_and_attested() {
    let text = read(".github/workflows/release.yml");
    let host = &text[text.find("\n  host:\n").expect("host job")..];
    let host = &host[..host.find("\n  announce:\n").expect("announce job")];
    let sums = host.find("SHA256SUMS").expect("SHA256SUMS step");
    let attest = host
        .find("uses: actions/attest-build-provenance@")
        .expect("attest step");
    let release = host.find("gh release create").expect("release step");
    assert!(
        sums < attest && attest < release,
        "checksums, then attestation, then release"
    );
    let host_perms = permissions(&text)
        .into_iter()
        .find(|(job, _)| job == "host")
        .unwrap()
        .1;
    for p in ["contents: write", "id-token: write", "attestations: write"] {
        assert!(host_perms.iter().any(|l| l == p), "host lacks {p}");
    }
}
